Code.Terraform:
```hcl
resource "aws_cloudwatch_log_delivery_source" "example_resource" {
  name = "example_resource-logs-source"
  # Critical: without an APPLICATION_LOGS source the extraction and consolidation logs are never emitted
  log_type     = "APPLICATION_LOGS"
  resource_arn = aws_bedrockagentcore_memory.example_resource.arn
}

resource "aws_cloudwatch_log_delivery_destination" "example_resource" {
  name = "example_resource-logs-destination"

  delivery_destination_configuration {
    destination_resource_arn = aws_cloudwatch_log_group.example_resource.arn
  }
}

# Critical: a delivery source with no delivery attached emits nothing
resource "aws_cloudwatch_log_delivery" "example_resource" {
  delivery_source_name     = aws_cloudwatch_log_delivery_source.example_resource.name
  delivery_destination_arn = aws_cloudwatch_log_delivery_destination.example_resource.arn
}
```
